const o=(n,t,a)=>n<t?t:n>a?a:n;export function spanFor(n,t){const a=o((n-.5)/.8,0,1);return t.narrowSpan+(t.wideSpan-t.narrowSpan)*a}export function distanceFor(n,t,a){const e=Math.atan(Math.tan(a*Math.PI/360)*t);return n/2/Math.tan(e)}export function cameraFor(n,t,a,e,s=null){let r=spanFor(n,t),x=a,i=e;if(s&&e){const c=Math.min(e.x,s.x)-t.includeMargin,p=Math.max(e.x,s.x)+t.includeMargin;r=o(p-c,r,t.maxSpan),i={x:(c+p)/2,z:e.z},x={minX:a.minX,maxX:Math.max(a.maxX,p)}}const h=distanceFor(r,n,t.fovDegrees),z=Math.hypot(t.height,t.back),y=t.height/z,X=t.back/z,M=Math.max(0,(x.maxX-x.minX)/2-r/2+1),g=(x.minX+x.maxX)/2;let u=t.target.x,m=t.target.z;if(i){u=o(i.x,g-M,g+M);const c=1-o((n-.5)/.8,0,1);m=t.target.z+(e.z-t.target.z)*.5*c}return{position:{x:u,y:t.target.y+y*h,z:m+X*h},target:{x:u,y:t.target.y,z:m},span:r,distance:h}}export function rayToGround(n,t){if(t.y>=-1e-6)return null;const a=-n.y/t.y;return{x:n.x+t.x*a,z:n.z+t.z*a}}export function ease(n,t,a,e){return t+(n-t)*Math.exp(-a*e)}
